var VALID_PRODUCT_TYPES = ["疗程卡", "家居产品"];
function defaultSkuUnit(productType) {
  return productType === "家居产品" ? "盒" : "次";
}
function normalizeSkuUnit(unit, productType) {
  if (unit === undefined)
    return { value: defaultSkuUnit(productType) };
  const value = unit.trim();
  if (!value)
    return { error: "单位不能为空" };
  if (value.length > 10)
    return { error: "单位不能超过 10 个字符" };
  return { value };
}
function validatePurchaseLimit(purchaseLimit) {
  if (purchaseLimit == null)
    return null;
  if (!Number.isInteger(purchaseLimit) || purchaseLimit < 1) {
    return "限购次数必须为正整数";
  }
  return null;
}
var createSku = withPermission("product:create", async (session4, data) => {
  if (!VALID_PRODUCT_TYPES.includes(data.productType)) {
    return { success: false, message: `无效的产品类型: ${data.productType}` };
  }
  const price = Number(data.price);
  if (isNaN(price) || price < 0) {
    return { success: false, message: "价格必须为非负数" };
  }
  if (data.serviceFee) {
    const fee = Number(data.serviceFee);
    if (isNaN(fee) || fee < 0) {
      return { success: false, message: "服务费必须为非负数" };
    }
  }
  if (data.productType === "疗程卡") {
    if (!data.sessionCount || data.sessionCount < 1) {
      return { success: false, message: "疗程卡的次数必须 >= 1" };
    }
  }
  const unitResult = normalizeSkuUnit(data.unit, data.productType);
  if (unitResult.error)
    return { success: false, message: unitResult.error };
  const purchaseLimitError = validatePurchaseLimit(data.purchaseLimit);
  if (purchaseLimitError)
    return { success: false, message: purchaseLimitError };
  try {
    await db2.insert(productSkus).values({
      ...data,
      unit: unitResult.value,
      productType: data.productType
    });
  } catch (err) {
    if (pgErrorCode(err) === "23505")
      return { success: false, message: "商品编号已存在" };
    if (pgErrorCode(err) === "23503")
      return { success: false, message: "品项分类不存在，请检查 categoryId" };
    throw err;
  }
  await logOperation(session4, "sku.create", "product_sku", data.skuId, { specName: data.specName });
  import_cache2.revalidatePath("/products");
  return { success: true, message: "商品创建成功" };
});
var updateSku = withPermission("product:update", async (session4, skuId, data, expectedUpdatedAt) => {
  const [before] = await db2.select().from(productSkus).where(import_drizzle_orm15.and(import_drizzle_orm15.eq(productSkus.skuId, skuId), import_drizzle_orm15.isNull(productSkus.deletedAt))).limit(1);
  if (before && (data.productType ?? before.productType) === "疗程卡") {
    const finalSessionCount = data.sessionCount !== undefined ? data.sessionCount : before.sessionCount;
    if (!finalSessionCount || finalSessionCount < 1) {
      return { success: false, message: "疗程卡的次数必须 >= 1" };
    }
  }
  const finalProductType = data.productType ?? before?.productType;
  let unitForUpdate;
  if (data.unit !== undefined) {
    const unitResult = normalizeSkuUnit(data.unit, finalProductType ?? "疗程卡");
    if (unitResult.error)
      return { success: false, message: unitResult.error };
    unitForUpdate = unitResult.value;
  } else if (before && data.productType !== undefined && data.productType !== before.productType) {
    unitForUpdate = defaultSkuUnit(data.productType);
  }
  const purchaseLimitError = validatePurchaseLimit(data.purchaseLimit);
  if (purchaseLimitError)
    return { success: false, message: purchaseLimitError };
  const whereConditions = expectedUpdatedAt ? import_drizzle_orm15.and(import_drizzle_orm15.eq(productSkus.skuId, skuId), import_drizzle_orm15.sql`date_trunc('milliseconds', ${productSkus.updatedAt}) = ${expectedUpdatedAt}`) : import_drizzle_orm15.eq(productSkus.skuId, skuId);
  const result = await db2.update(productSkus).set({
    ...data,
    ...unitForUpdate !== undefined ? { unit: unitForUpdate } : {},
    productType: data.productType
  }).where(whereConditions);
  if (result.count === 0) {
    return {
      success: false,
      message: expectedUpdatedAt ? "数据已被其他人修改，请刷新后重试" : "商品不存在"
    };
  }
  if (data.isEnabled !== undefined && before && before.isEnabled !== data.isEnabled) {
    const affected = await db2.select({ productId: mallProductSkus.productId }).from(mallProductSkus).innerJoin(products, import_drizzle_orm15.eq(products.productId, mallProductSkus.productId)).where(import_drizzle_orm15.and(import_drizzle_orm15.eq(mallProductSkus.skuId, skuId), import_drizzle_orm15.eq(products.isBundle, true)));
    const bundleIds = [...new Set(affected.map((a) => a.productId))];
    if (bundleIds.length > 0) {
      await db2.transaction(async (tx) => {
        for (const pid of bundleIds)
          await recomputeBundlePrice(pid, tx);
      });
    }
  }
  await logUpdate(session4, "sku.update", "product_sku", skuId, before, data);
  import_cache2.revalidatePath("/products");
  return { success: true, message: "规格已更新" };
});
