      return { success: false, message: "套餐商品的规格必须归入分组" };
    const [grp] = await db2.select({ id: mallBundleGroups.id }).from(mallBundleGroups).where(import_drizzle_orm15.and(import_drizzle_orm15.eq(mallBundleGroups.id, bundleGroupId), import_drizzle_orm15.eq(mallBundleGroups.productId, productId))).limit(1);
