    const result = await tx.update(mallProductSkus).set({ bundleGroupId }).where(import_drizzle_orm15.and(import_drizzle_orm15.eq(mallProductSkus.productId, productId), import_drizzle_orm15.eq(mallProductSkus.skuId, skuId)));
