var updateMallCategoryGroup = withPermission("product:update", async (session4, categoryId, data, expectedUpdatedAt) => {
  const [current] = await db2.select().from(mallCategories).where(import_drizzle_orm15.eq(mallCategories.categoryId, categoryId)).limit(1);
  if (!current) {
    return { success: false, message: "分组不存在" };
  }
  if (expectedUpdatedAt && current.updatedAt.toISOString() !== expectedUpdatedAt) {
    return { success: false, message: "数据已被其他人修改，请刷新后重试" };
  }
  const newName = data.categoryName?.trim();
  if (newName && newName !== current.categoryName) {
    const [dup] = await db2.select({ categoryId: mallCategories.categoryId }).from(mallCategories).where(import_drizzle_orm15.and(import_drizzle_orm15.sql`${mallCategories.categoryGroup} IS NULL`, import_drizzle_orm15.eq(mallCategories.categoryName, newName))).limit(1);
    if (dup) {
      return { success: false, message: `分组「${newName}」已存在` };
    }
  }
  await db2.transaction(async (tx) => {
    const updateData = {};
    if (newName !== undefined)
      updateData.categoryName = newName;
    if (data.sortOrder !== undefined)
      updateData.sortOrder = data.sortOrder;
    await tx.update(mallCategories).set(updateData).where(import_drizzle_orm15.eq(mallCategories.categoryId, categoryId));
    if (newName && newName !== current.categoryName) {
      await tx.update(mallCategories).set({ categoryGroup: newName }).where(import_drizzle_orm15.eq(mallCategories.categoryGroup, current.categoryName));
    }
  });
  await logUpdate(session4, "mall_category_group.update", "mall_category", categoryId, current, data);
  import_cache2.revalidatePath("/mall");
  return { success: true, message: "分组已更新" };
});
