// src/lib/member-pricing.ts
function isMember(customerType, memberLevel) {
  return customerType === "会员客" || memberLevel != null && memberLevel !== "";
}
function resolveUnitPrice(sku, member) {
  const listUnit = Number(sku.price) || 0;
  const special = sku.specialPrice == null || sku.specialPrice === "" ? null : Number(sku.specialPrice);
  const eligible = member === true;
  const realUnit = eligible && special !== null && special < listUnit ? special : listUnit;
  return { listUnit, realUnit };
}

// src/lib/treatment-tier-pricing.ts
function roundMoney(value) {
  return Math.round(value * 100) / 100;
}
function groupKey(row) {
  if (!row.categoryId || !row.specName)
    return null;
  return `${row.categoryId}::${row.specName}`;
}
function isEligibleLine(row) {
  return row.productType === "疗程卡" && row.isExperience !== true && row.isManagerSpecial !== true && row.isBundle !== true && Number(row.sessionCount) > 0 && groupKey(row) !== null;
}
function calculateTreatmentTierLineAmounts(lines, candidates, buyerIsMember, orderType) {
  const result = lines.map(() => null);
  if (orderType !== "销售单" && orderType !== "转换单")
    return result;
  const groups = new Map;
  lines.forEach((line5, index3) => {
    if (!isEligibleLine(line5))
      return;
    const key = groupKey(line5);
    const indexes3 = groups.get(key) ?? [];
    indexes3.push(index3);
    groups.set(key, indexes3);
  });
  for (const [key, indexes3] of groups) {
    const [categoryId, specName] = key.split("::");
    const totalSessions = indexes3.reduce((sum, index3) => {
      const line5 = lines[index3];
      return sum + Number(line5.sessionCount) * Math.max(1, Number(line5.quantity) || 1);
    }, 0);
    if (totalSessions <= 1)
      continue;
    const tier = candidates.filter((candidate) => candidate.categoryId === categoryId && candidate.specName === specName && candidate.productType === "疗程卡" && candidate.isExperience !== true && candidate.isManagerSpecial !== true && Number(candidate.sessionCount) > 1 && Number(candidate.sessionCount) <= totalSessions).map((candidate) => ({
      candidate,
      sessionCount: Number(candidate.sessionCount),
      amount: resolveUnitPrice(candidate, buyerIsMember).realUnit
    })).sort((left, right) => {
      const sessionDelta = right.sessionCount - left.sessionCount;
      if (sessionDelta !== 0)
        return sessionDelta;
      return left.amount / left.sessionCount - right.amount / right.sessionCount;
    })[0];
    if (!tier || tier.sessionCount <= 1 || !Number.isFinite(tier.amount) || tier.amount < 0)
      continue;
    for (const index3 of indexes3) {
      const line5 = lines[index3];
      const lineSessions = Number(line5.sessionCount) * Math.max(1, Number(line5.quantity) || 1);
      result[index3] = roundMoney(tier.amount * lineSessions / tier.sessionCount);
    }
  }
  return result;
}

