          paymentMethod: "储值卡",
          externalTxnId: null,
          externalTradeInfo: paymentIdempotencyFact,
          status: "已支付",
          sourceEnd: "admin",
          paidAt: nowTs(),
          operatorEmployeeId: session4.employeeId,
