// ../db/utils/member-level.ts
var LEVEL_RANK = {
  null: 0,
  "初钻": 1,
  "星钻": 2,
  "粉钻": 3,
  "金钻": 4,
  "黑钻": 5
};
function rank(level) {
  if (!level)
    return 0;
  return LEVEL_RANK[level] ?? 0;
}
function determineMemberLevel(spend, threshold) {
  if (spend >= 1e5)
    return "黑钻";
  if (spend >= 60000)
    return "金钻";
  if (spend >= 30000)
    return "粉钻";
  if (spend >= 1e4)
    return "星钻";
  if (spend >= threshold)
    return "初钻";
  return null;
}
function isDowngrade(from, to) {
  return rank(to) < rank(from);
}

