// src/lib/visit-points.ts
init_db_time();
var import_drizzle_orm40 = __toESM(require_drizzle_orm(), 1);
var VISIT_POINTS_CONFIG_KEY = "visit_points_reward";
var DEFAULT_VISIT_POINTS_REWARD = 20;
var VISIT_POINTS_EXTERNAL_REF_PREFIX = "visit-points";
function parseVisitPointsReward(value) {
  if (value === null || value === undefined || String(value).trim() === "") {
    return DEFAULT_VISIT_POINTS_REWARD;
  }
  const normalized = String(value).trim();
  if (!/^\d+$/.test(normalized))
    return 0;
  const amount = Number(normalized);
  return Number.isSafeInteger(amount) ? amount : 0;
}
function normalizeServiceDate(value) {
  if (value instanceof Date) {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Shanghai",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }).formatToParts(value);
    const pick2 = (type) => parts.find((part) => part.type === type)?.value ?? "";
    return `${pick2("year")}-${pick2("month")}-${pick2("day")}`;
  }
  const normalized = String(value || "").slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(normalized) ? normalized : "";
}
function buildVisitPointsExternalRef(userId, serviceDate) {
  return `${VISIT_POINTS_EXTERNAL_REF_PREFIX}:${userId}:${serviceDate}`;
}
function isVisitPointsEligible(snapshot) {
  return Boolean(snapshot.serviceOrderType === "售后" && snapshot.clientUserId && normalizeServiceDate(snapshot.serviceDate) && snapshot.remark !== DEPOSIT_REFUND_REMARK && snapshot.hasPositiveItem);
}
async function loadVisitPointsReward(executor) {
  const rows = await executor.execute(import_drizzle_orm40.sql`
    SELECT value FROM system_configs WHERE key = ${VISIT_POINTS_CONFIG_KEY} LIMIT 1
  `);
  return parseVisitPointsReward(rows[0]?.value);
}
async function grantVisitPointsEntry(executor, userId, serviceDate, amount, occurredAt, balanceUpdatedAt = occurredAt) {
  if (process.env.POINTS_ACCRUAL_ENABLED === "false" || amount <= 0) {
    return { granted: false, skipped: "disabled" };
  }
  const externalRef = buildVisitPointsExternalRef(userId, serviceDate);
  const grantedAtTs = instantTs(occurredAt);
  const balanceUpdatedTs = instantTs(balanceUpdatedAt);
  const result = await executor.execute(import_drizzle_orm40.sql`
    WITH inserted AS (
      INSERT INTO point_transactions
        (user_id, type, amount, ref_order_id, external_ref, created_at)
      VALUES (${userId}, '到店赠送', ${amount}, NULL, ${externalRef}, ${grantedAtTs})
      ON CONFLICT DO NOTHING
      RETURNING id, amount, created_at
    ),
    granted_batch AS (
      INSERT INTO point_batches
        (user_id, source_transaction_id, source_type, ref_order_id,
         original_amount, remaining_amount, earned_at, expire_at, created_at, updated_at)
      SELECT ${userId}, i.id, '到店赠送', NULL,
             i.amount, i.amount, i.created_at,
             i.created_at + INTERVAL '365 days', NOW(), NOW()
        FROM inserted i
    )
    UPDATE client_wechat_users
       SET points_balance = COALESCE(points_balance, 0) + (SELECT amount FROM inserted),
           points_updated_at = ${balanceUpdatedTs}
     WHERE user_id = ${userId}
       AND EXISTS (SELECT 1 FROM inserted)
    RETURNING points_balance
  `);
  return {
    granted: result.length > 0,
    skipped: result.length > 0 ? null : "duplicate",
    amount,
    externalRef
  };
}
async function insertVisitPointsFailure(executor, snapshot, source, detail) {
  await executor.execute(import_drizzle_orm40.sql`
    INSERT INTO operation_logs
      (action, target_type, target_id, detail, source, created_at)
    VALUES (
      'points.visitGrantFailed',
      'service_order',
      ${snapshot.serviceOrderId},
      ${JSON.stringify(detail)}::jsonb,
      ${source},
      NOW()
    )
  `);
}
async function grantVisitPointsSafe(tx, snapshot, source, now = new Date) {
  if (process.env.POINTS_ACCRUAL_ENABLED === "false" || !isVisitPointsEligible(snapshot)) {
    return { granted: false, skipped: "ineligible-or-disabled" };
  }
  const userId = snapshot.clientUserId;
  const serviceDate = normalizeServiceDate(snapshot.serviceDate);
  const externalRef = buildVisitPointsExternalRef(userId, serviceDate);
  let rewardAmount = DEFAULT_VISIT_POINTS_REWARD;
  try {
    return await tx.transaction(async (sp) => {
      rewardAmount = await loadVisitPointsReward(sp);
      return grantVisitPointsEntry(sp, userId, serviceDate, rewardAmount, now);
    });
  } catch (err) {
    const error = err instanceof Error ? err.message : String(err);
    const detail = {
      rewardAmount,
      externalRef,
      userId,
      serviceDate,
      error: error.slice(0, 500)
    };
    try {
      await tx.transaction(async (sp) => insertVisitPointsFailure(sp, snapshot, source, detail));
    } catch (logErr) {
      console.error("[visit-points] failure log failed:", logErr);
    }
    return { granted: false, skipped: "failed", amount: rewardAmount, externalRef, error };
  }
}

