        payableAmount: payAmount.toFixed(2),
        received: "0",
        firstPaymentAmount: null,
        couponId: null,
        couponDiscount: "0",
        paymentMethod: data.paymentMethod,
        openedBy: session4.employeeId,
        preferredEmployeeId: null,
        allocationStatus: "待分配",
        remark: data.remark || null,
        paidAt: null
