"use server";
function scalar2(rows, key = "v") {
  const r = rows[0];
  if (!r || r[key] == null)
    return 0;
  const n = Number(r[key]);
  return Number.isFinite(n) ? n : 0;
}
function ratio(num3, den) {
  if (num3 == null || den == null || den <= 0)
    return null;
  return num3 / den;
}
function performanceEventDateBetween(eventAlias, start, end) {
  return import_drizzle_orm65.sql`${import_drizzle_orm65.sql.raw(`${eventAlias}.status`)} = '已支付'
    AND ${import_drizzle_orm65.sql.raw(`${eventAlias}.performance_date`)} BETWEEN ${start} AND ${end}`;
}
function toMap(rows) {
  const m = new Map;
  for (const r of rows) {
    const id = r.store_id ?? r.market_id;
    if (id != null)
      m.set(String(id), Number(r.v ?? 0));
  }
  return m;
}
function assignRanks(rows) {
  let rank2 = 0;
  let lastValue = null;
  return rows.map((row, idx) => {
    if (row.value !== lastValue) {
      rank2 = idx + 1;
      lastValue = row.value;
    }
    return { ...row, rank: rank2 };
  });
}
