async function queryCoupons(payload) {
  const markets = await getMarkets2();
  const marketMap = new Map(markets.map((market) => [market.id, market.name]));
  return {
    sheetName: "优惠券",
    columns: mapColumns([
      { header: "券名称", width: 24, key: "name" },
      { header: "券类型", width: 10, key: "couponType" },
      { header: "面值/折扣", key: "discountValue", map: (row) => value(row, "couponType") === "折扣券" ? `${(Number(value(row, "discountValue")) * 10).toFixed(1)}折` : formatCurrency(value(row, "discountValue")) },
      { header: "使用条件", width: 16, key: "minSpend", map: (row) => Number(value(row, "minSpend")) > 0 ? `满${formatCurrency(value(row, "minSpend"))}可用` : "无门槛" },
      { header: "适用市场", width: 20, key: "applicableMarketIds", map: (row) => {
        const ids = value(row, "applicableMarketIds");
        return !ids?.length ? "全部市场" : ids.map((id) => marketMap.get(id) ?? id).join("、");
      } },
      { header: "有效期", width: 24, key: "validityMode", map: (row) => value(row, "validityMode") === "days" && value(row, "validDays") ? `领取后${value(row, "validDays")}天` : value(row, "validFrom") && value(row, "validTo") ? `${fmtDate(value(row, "validFrom"))} ~ ${fmtDate(value(row, "validTo"))}` : "—" },
      { header: "已发", key: "issuedCount" },
      { header: "总量", key: "totalCount", map: (row) => value(row, "couponType") === "折扣券" ? "" : cellOr(value(row, "totalCount"), "不限") },
      { header: "状态", width: 10, key: "isActive", map: (row) => value(row, "isActive") ? "启用" : "停用" },
      { header: "创建时间", width: 20, key: "createdAt", map: (row) => fmtDateTime(value(row, "createdAt")) },
      { header: "描述", width: 30, key: "description" }
    ]),
    rows: pagedRows((options) => exportCouponTemplates(payload, options))
  };
}
async function createExportContent(exportType, payload) {
  if (exportType === "data-center")
    return queryDataCenter(payload);
  const params = payload;
  switch (exportType) {
    case "orders":
      return {
        sheetName: "订单",
        columns: orderColumns,
        rows: aggregateContiguousExportRows(pagedRows((options) => exportOrders(params, options)), (row) => String(row.saleOrderId ?? row.__sourceId ?? ""), aggregateOrderExportRows)
      };
    case "payments":
      return {
        sheetName: "回款明细",
        columns: paymentColumns,
        rows: pagedRows((options) => exportOrderPayments(params, options))
      };
    case "refunds":
      return {
        sheetName: "退款明细",
        columns: refundColumns,
        rows: pagedRows((options) => exportRefunds(params, options))
      };
    case "allocation-sales":
      return {
        sheetName: "销售提成",
        columns: allocationSalesColumns,
        rows: aggregateContiguousExportRows(pagedRows((options) => exportAllocationOrders(params, options)), (row) => String(row.__salePaymentId ?? row.__sourceId ?? ""), aggregateAllocationExportRows)
      };
    case "allocation-services":
      return {
        sheetName: "服务提成",
        columns: serviceCommissionColumns,
        rows: pagedRows((options) => exportAllocationServiceOrders(params, options))
      };
    case "services":
      return {
        sheetName: "服务单消耗",
        columns: serviceColumns,
        rows: pagedRows((options) => exportServiceOrders(params, options))
      };
    case "customers":
      return {
        sheetName: "顾客",
        columns: customerColumns2,
        rows: pagedRows((options) => exportCustomers(params, options))
      };
    case "employees": {
      const nodes = await db2.select().from(orgNodes);
      const nodeMap = new Map(nodes.map((node) => [node.id, node]));
      const rows = async function* () {
        for await (const source of pagedRows((options) => exportEmployees(params, options))) {
          const path = [];
          let current = source.orgNodeId;
          const seen = new Set;
          while (current && !seen.has(current)) {
            seen.add(current);
            const node = nodeMap.get(current);
            if (!node)
              break;
            path.unshift(node.name);
            current = node.parentId;
          }
          yield { ...source, orgPath: path.join(" / ") };
        }
      }();
      return { sheetName: "员工", columns: employeeColumns, rows };
    }
    case "points":
      return {
        sheetName: "积分流水",
        columns: pointColumns,
        rows: pagedRows((options) => exportPointTransactions(params, options))
      };
    case "cards":
      return {
        sheetName: "疗程卡",
        columns: cardColumns,
        rows: pagedRows((options) => exportCards(params, options))
      };
    case "inventory-stocks": {
      const firstPage = await exportInventoryLots2(params, { limit: EXPORT_WORKER_BATCH_SIZE });
      return {
        sheetName: "库存批次",
        columns: inventoryColumns(firstPage.canViewPrice),
        rows: pagedRows((options) => exportInventoryLots2(params, options), firstPage)
      };
    }
    case "products":
      return queryProducts(params);
    case "mall-products":
      return queryMallProducts(params);
    case "coupons":
      return queryCoupons(params);
  }
}

// src/export-worker/file-name.ts
init_datetime();
function exportFileName(label, now = new Date) {
  const cleaned = label.replace(/[\\/:*?"<>|]/g, "-").replace(/\s+/g, " ").trim() || "导出数据";
  const timestamp5 = now.toLocaleTimeString("en-GB", {
    timeZone: "Asia/Shanghai",
    hour12: false
  }).replace(/:/g, "");
  return `${cleaned}_${shanghaiYmd(now)}${timestamp5}.xlsx`;
}
function exportCloudPath(jobId, fileName) {
  return `admin/exports/${jobId}/${fileName}`;
}

// src/export-worker/xlsx-writer.ts
var import_exceljs = __toESM(require_excel(), 1);
var XLSX_ROWS_PER_SHEET = 1e6;
function safeSheetName(input, sequence3) {
  const suffix = sequence3 === 1 ? "" : `-${sequence3}`;
  const base = input.replace(/[\\/?*\[\]:]/g, " ").trim() || "导出数据";
  return `${base.slice(0, Math.max(1, 31 - suffix.length))}${suffix}`;
}
async function writeStreamXlsx(options) {
  const workbook = new import_exceljs.default.stream.xlsx.WorkbookWriter({
    filename: options.filePath,
    useStyles: true,
    useSharedStrings: false
  });
  let rowCount = 0;
  let sheetCount = 0;
  let rowsInSheet = 0;
  const rowsPerSheet = Math.min(XLSX_ROWS_PER_SHEET, Math.max(1, Math.floor(options.rowsPerSheet ?? XLSX_ROWS_PER_SHEET)));
  const createSheet = () => {
    sheetCount += 1;
    rowsInSheet = 0;
    const worksheet2 = workbook.addWorksheet(safeSheetName(options.sheetName, sheetCount), {
      views: [{ state: "frozen", ySplit: 1 }]
    });
    worksheet2.columns = options.columns.map((column2) => ({ width: column2.width ?? 16 }));
    const header = worksheet2.addRow(options.columns.map((column2) => column2.header));
    header.font = { bold: true };
    header.commit();
    return worksheet2;
  };
  let worksheet = createSheet();
  for await (const sourceRow of options.rows) {
    if (rowsInSheet >= rowsPerSheet) {
      worksheet.commit();
      worksheet = createSheet();
    }
    const values2 = options.columns.map((column2) => column2.value(sourceRow) ?? "");
    worksheet.addRow(values2).commit();
    rowsInSheet += 1;
    rowCount += 1;
    if (rowCount % 1000 === 0)
      await options.onProgress?.(rowCount);
  }
  worksheet.commit();
  await workbook.commit();
  return { rowCount, sheetCount };
}

// src/lib/worker-heartbeat.ts
import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";
function runtimeStatusDir() {
  return process.env.SYSTEM_RUNTIME_DIR?.trim() || "/var/lib/fengyu/runtime-status";
}
function heartbeatPath(worker) {
  return path.join(runtimeStatusDir(), `${worker}.json`);
}
async function writeWorkerHeartbeat(worker, state = "idle", detail) {
  const dir = runtimeStatusDir();
  await mkdir(dir, { recursive: true, mode: 448 });
  const target = heartbeatPath(worker);
  const temp = `${target}.${process.pid}.${randomUUID()}.tmp`;
  const heartbeat = {
    worker,
    pid: process.pid,
    updatedAt: new Date().toISOString(),
    state,
    ...detail ? { detail: detail.slice(0, 120) } : {}
  };
  try {
    await writeFile(temp, `${JSON.stringify(heartbeat)}
`, { mode: 384 });
    await rename(temp, target);
  } catch (error) {
    await rm(temp, { force: true }).catch(() => {
      return;
    });
    throw error;
  }
}

// src/export-worker/worker-slots.ts
async function runWorkerSlots(options) {
  const concurrency = Math.max(1, Math.floor(options.concurrency));
  const runSlot = async (slot) => {
    while (!options.shouldStop()) {
      try {
        await options.runMaintenance();
        if (options.shouldStop())
          break;
        const job = await options.claimNextJob();
        if (job) {
          await options.processJob(job, slot);
        } else {
          await options.waitWhenIdle();
        }
      } catch (error) {
        options.onLoopError(error, slot);
        await options.waitWhenIdle();
      }
    }
  };
  await Promise.all(Array.from({ length: concurrency }, (_2, index3) => runSlot(index3 + 1)));
}
function createSerializedAsyncRunner(task) {
  let queue = Promise.resolve();
  return () => {
    queue = queue.catch(() => {
      return;
    }).then(task);
    return queue;
  };
}

// src/export-worker/index.ts
var POLL_INTERVAL_MS = 2000;
var MAINTENANCE_INTERVAL_MS = 60000;
var LEASE_MINUTES = 10;
var MAX_ATTEMPTS = 3;
var RETENTION_MS = 24 * 60 * 60 * 1000;
var MAX_CONCURRENT_JOBS = 2;
var stopping = false;
var maintenanceAt = 0;
var activeJobIds = new Set;
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
var publishWorkerHeartbeat = createSerializedAsyncRunner(async () => {
  const activeCount = activeJobIds.size;
  await writeWorkerHeartbeat("export-worker", activeCount > 0 ? "busy" : "idle", activeCount > 0 ? `正在处理 ${activeCount} 个导出任务` : undefined);
});
function asClaimedId(rows) {
  const row = rows[0];
  const id = Number(row?.id);
  return Number.isSafeInteger(id) && id > 0 ? id : null;
}
async function recoverExpiredLeases() {
  await db2.execute(import_drizzle_orm66.sql`
    UPDATE admin_export_jobs
       SET status = CASE
             WHEN attempt_count >= ${MAX_ATTEMPTS} THEN 'failed'
             ELSE 'queued'
           END,
           next_attempt_at = NOW(),
           lease_expires_at = NULL,
           error_code = 'WORKER_LEASE_EXPIRED',
           error_message = CASE
             WHEN attempt_count >= ${MAX_ATTEMPTS} THEN '导出任务执行超时，已达到最大重试次数'
             ELSE '导出任务执行超时，正在自动重试'
           END,
           completed_at = CASE
             WHEN attempt_count >= ${MAX_ATTEMPTS} THEN NOW()
             ELSE NULL
           END,
           updated_at = NOW()
     WHERE status = 'running'
       AND lease_expires_at IS NOT NULL
       AND lease_expires_at < NOW()
  `);
}
async function claimNextJob() {
  const claimed = await db2.execute(import_drizzle_orm66.sql`
    UPDATE admin_export_jobs
       SET status = 'running',
           attempt_count = attempt_count + 1,
           started_at = COALESCE(started_at, NOW()),
           lease_expires_at = NOW() + ${import_drizzle_orm66.sql.raw(`interval '${LEASE_MINUTES} minutes'`)},
           error_code = NULL,
           error_message = NULL,
           updated_at = NOW()
     WHERE id = (
       SELECT id
         FROM admin_export_jobs
        WHERE status = 'queued'
          AND next_attempt_at <= NOW()
        ORDER BY created_at ASC, id ASC
        FOR UPDATE SKIP LOCKED
        LIMIT 1
     )
     RETURNING id
  `);
  const id = asClaimedId(claimed);
  if (!id)
    return null;
  const [job] = await db2.select().from(adminExportJobs).where(import_drizzle_orm66.eq(adminExportJobs.id, id)).limit(1);
  return job ?? null;
}
async function renewLease(id) {
  await db2.execute(import_drizzle_orm66.sql`
    UPDATE admin_export_jobs
       SET lease_expires_at = NOW() + ${import_drizzle_orm66.sql.raw(`interval '${LEASE_MINUTES} minutes'`)},
           updated_at = NOW()
     WHERE id = ${id}
       AND status = 'running'
  `);
}
function safeFailure(err) {
  const message2 = err instanceof Error ? err.message : String(err);
  const parsed = parseErrorPrefix(message2);
  if (parsed)
    return { code: parsed.prefix, message: parsed.displayMessage.slice(0, 500) };
  return { code: "EXPORT_FAILED", message: "导出生成失败，系统将自动重试" };
}
async function failJob(job, err) {
  const failure = safeFailure(err);
  const shouldRetry = job.attemptCount < MAX_ATTEMPTS;
  await db2.update(adminExportJobs).set({
    status: shouldRetry ? "queued" : "failed",
    nextAttemptAt: shouldRetry ? new Date(Date.now() + job.attemptCount * 30000) : new Date,
    leaseExpiresAt: null,
    completedAt: shouldRetry ? null : new Date,
    errorCode: failure.code,
    errorMessage: shouldRetry ? `${failure.message}（第 ${job.attemptCount} 次失败，正在重试）` : failure.message
  }).where(import_drizzle_orm66.and(import_drizzle_orm66.eq(adminExportJobs.id, job.id), import_drizzle_orm66.eq(adminExportJobs.status, "running")));
  if (!shouldRetry) {
    const session4 = parseExportSession(job.scopeSnapshot);
    await logOperation(session4, "export_job.failed", "admin_export_jobs", String(job.id), {
      exportType: job.exportType,
      attemptCount: job.attemptCount,
      errorCode: failure.code
    }).catch((logError) => console.error("[export-worker] failure audit log error:", logError));
  }
}
async function expireFinishedFiles() {
  const expired = await db2.select({ id: adminExportJobs.id, fileCloudPath: adminExportJobs.fileCloudPath }).from(adminExportJobs).where(import_drizzle_orm66.and(import_drizzle_orm66.inArray(adminExportJobs.status, ["ready", "expired"]), import_drizzle_orm66.isNotNull(adminExportJobs.fileCloudPath), import_drizzle_orm66.lt(adminExportJobs.expiresAt, new Date))).limit(100);
  for (const job of expired) {
    try {
      if (job.fileCloudPath)
        await deleteByCloudPaths([job.fileCloudPath]);
      await db2.update(adminExportJobs).set({ status: "expired", fileCloudPath: null, updatedAt: new Date }).where(import_drizzle_orm66.and(import_drizzle_orm66.eq(adminExportJobs.id, job.id), import_drizzle_orm66.inArray(adminExportJobs.status, ["ready", "expired"])));
    } catch (err) {
      console.error(`[export-worker] cleanup failed for job ${job.id}:`, err);
    }
  }
}
async function runMaintenance() {
  const now = Date.now();
  if (now - maintenanceAt < MAINTENANCE_INTERVAL_MS)
    return;
  maintenanceAt = now;
  await recoverExpiredLeases();
  await expireFinishedFiles();
}
async function processJob(job) {
  let tempDir = null;
  let cloudPath = null;
  const jobStartedAt = Date.now();
  activeJobIds.add(job.id);
  await publishWorkerHeartbeat().catch(() => {
    return;
  });
  const heartbeat = setInterval(() => {
    renewLease(job.id).catch((err) => console.error(`[export-worker] lease renew failed for ${job.id}:`, err));
  }, 30000);
  heartbeat.unref();
  try {
    const exportType = parseExportType(job.exportType);
    if (!exportType) {
      await failJob(job, new Error("INVALID_STATE: 导出任务类型异常"));
      return;
    }
    const session4 = parseExportSession(job.scopeSnapshot);
    const payload = parseExportPayload(exportType, job.requestPayload);
    tempDir = await mkdtemp(path2.join(tmpdir(), "fengyu-export-"));
    const generateStartedAt = Date.now();
    const output = await runWithExportSession(session4, async () => {
      const content = await createExportContent(exportType, payload);
      const fileName = exportFileName(exportJobLabel(exportType, payload));
      const filePath = path2.join(tempDir, fileName);
      let lastProgress = 0;
      const writeResult = await writeStreamXlsx({
        filePath,
        sheetName: content.sheetName,
        columns: content.columns,
        rows: content.rows,
        onProgress: async (rowCount) => {
          if (rowCount - lastProgress < 1000)
            return;
          lastProgress = rowCount;
          await db2.update(adminExportJobs).set({ progressRows: rowCount }).where(import_drizzle_orm66.and(import_drizzle_orm66.eq(adminExportJobs.id, job.id), import_drizzle_orm66.eq(adminExportJobs.status, "running")));
        }
      });
      return { content, fileName, filePath, writeResult };
    });
    const generateMs = Date.now() - generateStartedAt;
    if (output.writeResult.rowCount === 0) {
      await db2.update(adminExportJobs).set({
        status: "empty",
        leaseExpiresAt: null,
        completedAt: new Date,
        rowCount: 0,
        sheetCount: 0,
        progressRows: 0,
        errorCode: null,
        errorMessage: null
      }).where(import_drizzle_orm66.and(import_drizzle_orm66.eq(adminExportJobs.id, job.id), import_drizzle_orm66.eq(adminExportJobs.status, "running")));
      await logOperation(session4, "export_job.empty", "admin_export_jobs", String(job.id), {
        exportType
      }).catch((logError) => console.error("[export-worker] empty audit log error:", logError));
      console.log(`[export-worker] job ${job.id} empty (generate=${generateMs}ms total=${Date.now() - jobStartedAt}ms)`);
      return;
    }
    const uploadPath = exportCloudPath(job.id, output.fileName);
    const uploadStartedAt = Date.now();
    await uploadFile(createReadStream(output.filePath), uploadPath);
    const uploadMs = Date.now() - uploadStartedAt;
    cloudPath = uploadPath;
    const expiresAt = new Date(Date.now() + RETENTION_MS);
    await db2.update(adminExportJobs).set({
      status: "ready",
      leaseExpiresAt: null,
      completedAt: new Date,
      expiresAt,
      progressRows: output.writeResult.rowCount,
      rowCount: output.writeResult.rowCount,
      sheetCount: output.writeResult.sheetCount,
      fileCloudPath: cloudPath,
      fileName: output.fileName,
      errorCode: null,
      errorMessage: null
    }).where(import_drizzle_orm66.and(import_drizzle_orm66.eq(adminExportJobs.id, job.id), import_drizzle_orm66.eq(adminExportJobs.status, "running")));
    await logOperation(session4, "export_job.ready", "admin_export_jobs", String(job.id), {
      exportType,
      rowCount: output.writeResult.rowCount,
      sheetCount: output.writeResult.sheetCount
    }).catch((logError) => console.error("[export-worker] ready audit log error:", logError));
    const queueWaitMs = Math.max(0, jobStartedAt - job.createdAt.getTime());
    console.log(`[export-worker] job ${job.id} ready (${output.writeResult.rowCount} rows, queue=${queueWaitMs}ms generate=${generateMs}ms upload=${uploadMs}ms total=${Date.now() - jobStartedAt}ms)`);
  } catch (err) {
    console.error(`[export-worker] job ${job.id} failed:`, err);
    if (cloudPath) {
      await deleteByCloudPaths([cloudPath]).catch((cleanupError) => {
        console.error(`[export-worker] failed upload cleanup for ${job.id}:`, cleanupError);
      });
    }
    await failJob(job, err);
  } finally {
    clearInterval(heartbeat);
    activeJobIds.delete(job.id);
    await publishWorkerHeartbeat().catch(() => {
      return;
    });
    if (tempDir)
      await rm2(tempDir, { recursive: true, force: true }).catch((err) => {
        console.error(`[export-worker] temp cleanup failed for ${job.id}:`, err);
      });
  }
}
async function run() {
  console.log(`[export-worker] started (global concurrency: ${MAX_CONCURRENT_JOBS})`);
  await publishWorkerHeartbeat();
  const workerHeartbeat = setInterval(() => {
    publishWorkerHeartbeat().catch(() => {
      return;
    });
  }, 30000);
  workerHeartbeat.unref();
  await runWorkerSlots({
    concurrency: MAX_CONCURRENT_JOBS,
    shouldStop: () => stopping,
    runMaintenance,
    claimNextJob,
    processJob: async (job, slot) => {
      console.log(`[export-worker] slot ${slot} claimed job ${job.id}`);
      await processJob(job);
    },
    waitWhenIdle: () => sleep(POLL_INTERVAL_MS),
    onLoopError: (err, slot) => console.error(`[export-worker] slot ${slot} loop error:`, err)
  });
  clearInterval(workerHeartbeat);
  await publishWorkerHeartbeat().catch(() => {
    return;
  });
  console.log("[export-worker] stopped");
}
process.on("SIGTERM", () => {
  stopping = true;
});
process.on("SIGINT", () => {
  stopping = true;
});
if (process.argv.includes("--check")) {
  console.log("[export-worker] bundle verified");
} else if (process.argv.includes("--once")) {
  runMaintenance().then(claimNextJob).then(async (job) => {
    if (job)
      await processJob(job);
  }).then(() => process.exit(0)).catch((err) => {
    console.error("[export-worker] one-shot failed:", err);
    process.exit(1);
  });
} else {
  run().catch((err) => {
    console.error("[export-worker] fatal error:", err);
    process.exit(1);
  });
}
